dataset.prompt_raw_json:
{
  "parts": [
    {
      "text": "I use docuctl 2.x. How do I roll production back to r41?"
    }
  ],
  "role": "user"
}

dataset.reference_raw_json:
{
  "parts": [
    {
      "text": "Run `docuctl rollback --env production --to r41`. Note that `docuctl release revert` was removed in 2.0 and database migrations are not rolled back automatically."
    }
  ],
  "role": "model"
}

dataset.response_raw_json:
{
  "parts": [
    {
      "text": "In docuctl 2.x, run:\n\n```bash\ndocuctl rollback --env production --to r41\n```\n\nThis points production traffic back to release `r41` without rebuilding. Note that database migrations are not automatically rolled back."
    }
  ],
  "role": "model"
}

dataset.prompt_raw_json:
{
  "parts": [
    {
      "text": "How do I create a deploy token for staging CI and check when tokens expire?"
    }
  ],
  "role": "user"
}

dataset.reference_raw_json:
{
  "parts": [
    {
      "text": "Run `docuctl tokens create --name ci-docs-api --scope deploy:staging` and store it as `DOCUCTL_TOKEN`. Tokens expire after 90 days; check expiry with `docuctl tokens list`."
    }
  ],
  "role": "model"
}
